SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
  BEGIN TRANSACTION;
  IF SCHEMA_ID(N'bbva') IS NULL EXEC(N'CREATE SCHEMA bbva');
  IF OBJECT_ID(N'bbva.EngineeringSpecialtyCatalog',N'U') IS NULL
  BEGIN
    CREATE TABLE bbva.EngineeringSpecialtyCatalog(
      Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_BBVA_EngineeringSpecialtyCatalog PRIMARY KEY DEFAULT NEWID(),
      N3 NVARCHAR(180) NOT NULL,Guild NVARCHAR(220) NOT NULL,Specialty NVARCHAR(220) NOT NULL,
      GuildLeader NVARCHAR(220) NULL,SpecialtyOwner NVARCHAR(220) NULL,PortfolioStaffing NVARCHAR(220) NULL,Staffer NVARCHAR(220) NULL,
      Status NVARCHAR(16) NOT NULL CONSTRAINT DF_BBVA_EngineeringSpecialty_Status DEFAULT N'ACTIVE',
      CreatedAt DATETIME2(7) NOT NULL CONSTRAINT DF_BBVA_EngineeringSpecialty_CreatedAt DEFAULT SYSUTCDATETIME(),
      UpdatedAt DATETIME2(7) NOT NULL CONSTRAINT DF_BBVA_EngineeringSpecialty_UpdatedAt DEFAULT SYSUTCDATETIME(),
      CreatedByEmail NVARCHAR(320) NOT NULL,UpdatedByEmail NVARCHAR(320) NOT NULL,
      CONSTRAINT CK_BBVA_EngineeringSpecialty_Status CHECK(Status IN(N'ACTIVE',N'INACTIVE',N'DELETED'))
    );
    CREATE UNIQUE INDEX UX_BBVA_EngineeringSpecialty_Hierarchy ON bbva.EngineeringSpecialtyCatalog(N3,Guild,Specialty);
    CREATE INDEX IX_BBVA_EngineeringSpecialty_Status ON bbva.EngineeringSpecialtyCatalog(Status,N3,Guild,Specialty);
  END;
  DECLARE @Seed TABLE(N3 NVARCHAR(180),Guild NVARCHAR(220),Specialty NVARCHAR(220),GuildLeader NVARCHAR(220),SpecialtyOwner NVARCHAR(220),PortfolioStaffing NVARCHAR(220),Staffer NVARCHAR(220));

  MERGE bbva.EngineeringSpecialtyCatalog AS target
  USING @Seed AS source ON target.N3=source.N3 AND target.Guild=source.Guild AND target.Specialty=source.Specialty
  WHEN MATCHED THEN UPDATE SET GuildLeader=source.GuildLeader,SpecialtyOwner=source.SpecialtyOwner,PortfolioStaffing=source.PortfolioStaffing,Staffer=source.Staffer,UpdatedAt=SYSUTCDATETIME(),UpdatedByEmail=N'system.v26@basebfs.local'
  WHEN NOT MATCHED THEN INSERT(N3,Guild,Specialty,GuildLeader,SpecialtyOwner,PortfolioStaffing,Staffer,Status,CreatedByEmail,UpdatedByEmail)
    VALUES(source.N3,source.Guild,source.Specialty,source.GuildLeader,source.SpecialtyOwner,source.PortfolioStaffing,source.Staffer,N'ACTIVE',N'system.v26@basebfs.local',N'system.v26@basebfs.local');
  IF OBJECT_ID(N'bbva.SecondTechnologyCertificationPlan',N'U') IS NULL
  BEGIN
    CREATE TABLE bbva.SecondTechnologyCertificationPlan(
      Id UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_BBVA_SecondTechnologyCertificationPlan PRIMARY KEY DEFAULT NEWID(),
      PersonId UNIQUEIDENTIFIER NOT NULL,CertificationId UNIQUEIDENTIFIER NOT NULL,
      Status NVARCHAR(24) NOT NULL CONSTRAINT DF_BBVA_SecondCertificationPlan_Status DEFAULT N'PLANNED',TargetDate DATE NULL,Notes NVARCHAR(1000) NULL,
      CreatedAt DATETIME2(7) NOT NULL CONSTRAINT DF_BBVA_SecondCertificationPlan_CreatedAt DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2(7) NOT NULL CONSTRAINT DF_BBVA_SecondCertificationPlan_UpdatedAt DEFAULT SYSUTCDATETIME(),
      CreatedByEmail NVARCHAR(320) NOT NULL,UpdatedByEmail NVARCHAR(320) NOT NULL,
      CONSTRAINT FK_BBVA_SecondCertificationPlan_Person FOREIGN KEY(PersonId) REFERENCES bbva.Person(Id),
      CONSTRAINT FK_BBVA_SecondCertificationPlan_Cert FOREIGN KEY(CertificationId) REFERENCES bbva.CertificationCatalog(Id),
      CONSTRAINT CK_BBVA_SecondCertificationPlan_Status CHECK(Status IN(N'PLANNED',N'IN_PROGRESS',N'COMPLETED',N'CANCELLED',N'DELETED'))
    );
    CREATE UNIQUE INDEX UX_BBVA_SecondCertificationPlan_PersonCertification ON bbva.SecondTechnologyCertificationPlan(PersonId,CertificationId);
    CREATE INDEX IX_BBVA_SecondCertificationPlan_Status ON bbva.SecondTechnologyCertificationPlan(Status,UpdatedAt DESC);
  END;
  IF OBJECT_ID(N'bbva.PersonCertificationAttempt',N'U') IS NOT NULL
  BEGIN
    IF COL_LENGTH(N'bbva.PersonCertificationAttempt',N'UpdatedAt') IS NULL ALTER TABLE bbva.PersonCertificationAttempt ADD UpdatedAt DATETIME2(7) NULL;
    IF COL_LENGTH(N'bbva.PersonCertificationAttempt',N'UpdatedByEmail') IS NULL ALTER TABLE bbva.PersonCertificationAttempt ADD UpdatedByEmail NVARCHAR(320) NULL;
  END;
  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;
